"""Public bespoke Les EX page. Content and captions are in heart-page.json."""
from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'assets/i18n/heart-page.json').read_text(encoding='utf-8'))
LANGS=('fr','en','ja')
MEDIA='/assets/media/les-ex/'
def text(key,lang):return DATA['copy'][key][LANGS.index(lang)]
def render(lang):
 i=LANGS.index(lang);e=lambda key:escape(text(key,lang));store='https://apps.microsoft.com/detail/9NKH7Z996H68?hl='+{'fr':'fr-fr','en':'en-us','ja':'ja-jp'}[lang]
 actors=''.join(f'''<figure class="ex-actor ex-actor-{c['key']}" data-ex-actor="{c['key']}"><img src="{MEDIA}characters/{c['key']}.webp" alt="{escape(c['name'][i])}" width="480" height="1000" fetchpriority="{'high' if n==0 else 'auto'}"><figcaption><button type="button" data-ex-character="{c['key']}" data-note="{escape(c['note'][i],quote=True)}" aria-pressed="false">{escape(c['name'][i])}</button></figcaption></figure>''' for n,c in enumerate(DATA['characters']))
 shots=''.join(f'''<figure class="ex-shot"><a href="{MEDIA}screens/{s['key']}.png" data-ex-lightbox aria-label="{e('view')} · {escape(s['title'][i],quote=True)}"><img src="{MEDIA}screens/{s['key']}-900.webp" srcset="{MEDIA}screens/{s['key']}-900.webp 900w, {MEDIA}screens/{s['key']}-1600.webp 1600w" sizes="(min-width:900px) {'1100px' if n==0 else '550px'}, 95vw" alt="{escape(s['title'][i]+'. '+s['caption'][i],quote=True)}" width="1738" height="977" loading="lazy"><span class="ex-zoom" aria-hidden="true">↗</span></a><figcaption><span class="ex-shot-number">0{n+1}</span><div><h3>{escape(s['title'][i])}</h3><p>{escape(s['caption'][i])}</p></div></figcaption></figure>''' for n,s in enumerate(DATA['screens']))
 names={'fr':'Français','en':'English','ja':'日本語'}
 trailers=''.join(f'<a href="{MEDIA}trailers/{code}.mp4" data-ex-trailer="{code}" data-poster="{MEDIA}trailers/{code}-poster.webp" data-track="{MEDIA}trailers/{code}.vtt" lang="{code}" aria-current="{str(code==lang).lower()}">{names[code]}</a>' for code in LANGS)
 return f'''
<section class="ex-hero" aria-labelledby="ex-title"><div class="ex-petals" aria-hidden="true">{''.join('<span></span>' for _ in range(9))}</div><div class="ex-hero-inner"><div class="ex-hero-copy"><p class="ex-eyebrow">{e('eyebrow')}</p><h1 id="ex-title" class="ex-title"><span>Les EX</span><span>de l’haut delà</span></h1><p class="ex-tagline">{e('tagline')}</p><p class="ex-intro">{e('intro')}</p><div class="ex-actions"><a class="ex-play" href="{store}" target="_blank" rel="noopener noreferrer">{e('demo')} <span aria-hidden="true">↗</span></a><a class="ex-watch" href="#trailers">▶ {e('watch')}</a></div><p class="ex-free">{e('free')}</p></div><div class="ex-cast" role="group" aria-label="{e('choose')}">{actors}<p class="ex-character-note" id="ex-character-note" aria-live="polite">{e('choose')}</p></div></div><div class="ex-hero-bottom"><span aria-hidden="true">✦ Aozora · Love is complicated!</span><button class="ex-motion-toggle" type="button" data-ex-motion aria-pressed="false" data-enable="{e('motion_off')}" data-reduce="{e('motion')}">{e('motion')}</button></div></section>
<section class="ex-section ex-trailers" id="trailers" aria-labelledby="ex-trailer-title"><div class="ex-section-head"><p class="ex-eyebrow">01 / TRAILER</p><h2 id="ex-trailer-title">{e('trailer_title')}</h2><p>{e('trailer_intro')}</p></div><nav class="ex-trailer-languages" aria-label="{e('watch')}">{trailers}</nav><video id="ex-trailer" controls preload="none" playsinline poster="{MEDIA}trailers/{lang}-poster.webp" width="1280" height="720"><source src="{MEDIA}trailers/{lang}.mp4" type="video/mp4"><track kind="captions" src="{MEDIA}trailers/{lang}.vtt" srclang="{lang}" label="{names[lang]}"><a href="{MEDIA}trailers/{lang}.mp4">{e('video_fallback')}</a></video></section>
<section class="ex-section ex-screens" aria-labelledby="ex-screens-title"><div class="ex-section-head"><p class="ex-eyebrow">02 / AOZORA</p><h2 id="ex-screens-title">{e('screens_title')}</h2><p class="ex-version">{e('version')}</p></div><div class="ex-gallery">{shots}</div></section>
<section class="ex-section ex-finale"><span aria-hidden="true">♡</span><h2>{e('last_title')}</h2><p>{e('last_text')}</p><a class="ex-play" href="{store}" target="_blank" rel="noopener noreferrer">{e('demo')} ↗</a><p class="ex-free">{e('free')}</p></section>
<dialog class="ex-lightbox" id="ex-lightbox" aria-label="{e('view')}"><button type="button" class="ex-lightbox-close" data-ex-close aria-label="{e('close')}">✕</button><img id="ex-lightbox-image" alt="" width="1738" height="977"><p id="ex-lightbox-caption"></p><div class="ex-lightbox-nav"><button type="button" data-ex-previous aria-label="{e('previous')}">←</button><span id="ex-lightbox-position" aria-live="polite"></span><button type="button" data-ex-next aria-label="{e('next')}">→</button></div></dialog>
'''
